(() => {
  const list = document.querySelector('.dshcb-group-list')
  const items = [...(list?.querySelectorAll('.dshcb-group-item') ?? [])]
  if (list === null || items.length < 7) return false
  return list.clientHeight <= 132 && list.scrollHeight > list.clientHeight && getComputedStyle(list).overflowY === 'auto'
})()

