(() => {
  const items = [...document.querySelectorAll('.dshcb-group-item')]
  if (items.length < 7) return false
  return items.every((item) => {
    const children = [...item.children]
    const checkbox = children.find((child) => child.tagName === 'INPUT')
    const thumb = children.find((child) => child.tagName === 'IMG')
    const name = children.find((child) => child.classList.contains('dshcb-group-name'))
    const checkedIndex = children.indexOf(checkbox)
    const thumbIndex = children.indexOf(thumb)
    const nameIndex = children.indexOf(name)
    return checkbox !== undefined && thumb !== undefined && name !== undefined && checkedIndex < thumbIndex && thumbIndex < nameIndex && thumb.getAttribute('src').includes('/chat-backgrounds/files/')
  })
})()

