(async () => {
  const item = (name) => [...document.querySelectorAll('.dshcb-group-item')].find((row) => row.querySelector('.dshcb-group-name')?.innerText.trim() === name)
  const from = item('sample-background-2.png')
  const to = item('sample-background-3.png')
  if (from === undefined || to === undefined) return 'MISSING ITEMS'
  const handle = from.querySelector('.dshcb-drag-handle')
  const transfer = new DataTransfer()
  handle.dispatchEvent(new DragEvent('dragstart', { dataTransfer: transfer, bubbles: true, cancelable: true }))
  await new Promise((resolve) => setTimeout(resolve, 80))
  to.dispatchEvent(new DragEvent('dragover', { dataTransfer: transfer, bubbles: true, cancelable: true }))
  to.dispatchEvent(new DragEvent('drop', { dataTransfer: transfer, bubbles: true, cancelable: true }))
  handle.dispatchEvent(new DragEvent('dragend', { dataTransfer: transfer, bubbles: true, cancelable: true }))
  await new Promise((resolve) => setTimeout(resolve, 200))
  const stored = JSON.parse(localStorage.getItem('dsh-chat-background:rotation-group') ?? '[]')
  const shown = [...document.querySelectorAll('.dshcb-group-item[data-selected] .dshcb-group-name')].map((el) => el.innerText.trim())
  return JSON.stringify({ stored, shown })
})()

